// El sync word real del mando. En el aire va DENTRO del payload del
// SX1280, porque el campo PreambleLength del chip satura en 32 bits y el
// preambulo real del mando son 62: los ultimos 40 van como sync word del
// chip (aaaaaaaad6) y estos 5 bytes encabezan el payload de 45.
static const uint8_t CECOTEC_SYNC[5] = {0xfb, 0x22, 0xe3, 0xe7, 0xde,};
static const uint8_t CECOTEC_CHIP_SYNC[5] = {0xaa, 0xaa, 0xaa, 0xaa, 0xd6};
static const uint16_t CECOTEC_CHIP_PREAMBLE_BITS = 24;

